def esc(s):return html.escape(str(s),quote=True)
def fo(x,y,w,h,text,size=36,color='#152d42'):
 return f'<foreignObject x="{x}" y="{y}" width="{w}" height="{h}"><div xmlns="http://www.w3.org/1999/xhtml" lang="th" style="font-family:Leelawadee UI,Tahoma,sans-serif;font-size:{size}px;line-height:1.32;color:{color};overflow-wrap:anywhere">{text}</div></foreignObject>'
def photo_svg(case,index,source):
 im=Image.open(source);w,h=im.size;scale=min(1050/w,1500/h);ww,hh=w*scale,h*scale;ox=30+(1050-ww)/2;oy=185+(1500-hh)/2
 uri='data:image/png;base64,'+base64.b64encode(source.read_bytes()).decode()
 s=['<svg xmlns="http://www.w3.org/2000/svg" width="1800" height="1900" viewBox="0 0 1800 1900">','<rect width="1800" height="1900" fill="white"/>',fo(35,20,1730,85,f'<b>กล่อง {case["id"]:02d} • {esc(case["sides"][index])}</b>',54),fo(35,105,1720,72,'กรอบสีส้ม = บริเวณสำรวจจากภาพ ไม่ใช่จุดวัดหรือผังต่อไฟที่ยืนยันแล้ว',35),f'<image x="{ox}" y="{oy}" width="{ww}" height="{hh}" href="{uri}"/>']
 for n,zone in enumerate(case['zones'][index]):
  x1,y1,x2,y2=zone['box'];x,y=ox+x1*scale,oy+y1*scale;rw,rh=(x2-x1)*scale,(y2-y1)*scale
  s.append(f'<rect x="{x}" y="{y}" width="{rw}" height="{rh}" rx="7" fill="none" stroke="#e88909" stroke-width="5" stroke-dasharray="13 7"/>')
  s.append(f'<rect x="{x}" y="{y}" width="92" height="48" rx="6" fill="#f89c1c"/>')
  s.append(fo(x+4,y+2,90,46,f'<b>{zone["code"]}</b>',32,'#111'))
  cy=220+n*235;s.append(f'<rect x="1110" y="{cy-12}" width="655" height="220" rx="14" fill="#fff6e8"/>')
  s.append(fo(1130,cy,615,202,f'<b>{zone["code"]} {esc(zone["title"])}</b><br/>{esc(zone["note"])}<br/><b>ค่าแรงดัน: ยังไม่ยืนยัน</b>',34))
 s.append('<rect x="30" y="1735" width="1740" height="125" rx="14" fill="#eef4f8"/>')
 s.append(fo(55,1755,1690,100,'กราวด์อ้างอิง / จุดแดง / สภาวะเปิดทำงาน: ยังไม่ยืนยัน • ยังไม่ควรจ่ายไฟจากรูปนี้<br/>ภาพต้นฉบับผู้ใช้ + ชั้นกำกับเวกเตอร์ • ไม่ได้ทดสอบกับกล่องจริง',33))
 s.append('</svg>');return ''.join(s)

pages=[];inventory=[]
def page(content,cls='text'):pages.append(f'<section class="{cls}">{content}</section>')
page('<h1>อ่านวงจรจากภาพกล่องจริง</h1><h2>ทะเบียนกล่อง 01–07</h2><p>ฉบับสำรวจภาพและวางแผนพิสูจน์วงจร • 23 ตุลาคม 2569</p><p>หนังสือชุดนี้ใช้ภาพที่ผู้ใช้ส่ง 19 ภาพ แยกตัวกล่องทุกใบ ไม่ระบุว่าเป็น 1KD/2KD หรือใช้กับ P0093 จนกว่าจะจับคู่หมายเลขอุปกรณ์และเอกสารได้</p><div class="notice"><b>ภาพบอกตำแหน่งได้ แต่ยังไม่บอกแรงดันของเน็ต</b><p>ยังไม่มีจุดบนแผงใดที่ยืนยันขาไฟเข้า กราวด์ รางภายใน หรือค่าแรงดันเฉพาะได้จากภาพชุดนี้ การใส่ตัวเลขที่คาดเดาลงบนแพดจริงอาจทำให้วัดผิดจุด</p></div><h2>วิธีอ่านภาพกำกับ</h2><p>กรอบประสีส้มและรหัส A/B/C/I/E/H เป็นชื่อบริเวณสำรวจที่ตั้งขึ้น ไม่ใช่หมายเลขขาหรือชื่อ test point OEM ด้าน A/B เป็นชื่อภาพในแฟ้ม ไม่ใช่หลักฐานว่าพิกัดตรงกันหลังพลิกแผง</p><p>คำว่า “กลุ่มกำลัง” อธิบายแพ็กเกจและบริเวณที่เห็น ไม่รับรองว่าเป็นเรกูเลเตอร์ ภาคหัวฉีด หรือภาคคอยล์ ส่วนคำว่าคราบบอกลักษณะภาพ ไม่ใช่ผลวินิจฉัยความเสียหาย</p><h2>สิ่งที่มีในชุดนี้</h2><p>ภาพกำกับต้นฉบับครบทุกภาพ • แผ่นวงจรสอนอ่านแยกจากวงจรจริง • ลำดับไล่ไฟ • ตารางบันทึกการพิสูจน์ • ผลตรวจโดยเอเจนต์</p><p>กรณี 6 มีป้ายเตือนแรงดันสูง กรณี 7 มีลวดเชื่อมละเอียด ต้องใช้วิธีเฉพาะโมดูลก่อนสัมผัสหรือทดสอบภายใน</p>')
page('<h1>ไล่วงจรจริงอย่างไร</h1><p class="notice">นี่คือลำดับเก็บหลักฐาน ไม่ใช่ผังต่อสายทดสอบของกล่องทั้ง 7</p><ol><li><b>ยืนยันตัวกล่องและทิศปลั๊ก</b> ใช้ฉลาก เบอร์อุปกรณ์ มุมมองหน้าปลั๊ก และคู่มือที่ตรงกัน ชื่อบน PCB ยังไม่เพียงพอ</li><li><b>ตรวจแบบไม่จ่ายไฟ</b> ถอดแหล่งพลังงาน ตรวจแรงดันตกค้างตามขั้นตอนตรงโมดูลก่อนใช้ Ω / continuity; ไม่คายประจุด้วยการชอร์ต</li><li><b>พิสูจน์กราวด์อ้างอิง</b> แยกกราวด์กำลัง กราวด์สัญญาณ และตัวเรือน รูยึดหรือแท็บโลหะไม่ใช่ GND โดยอัตโนมัติ</li><li><b>ไล่ทีละช่วง</b> ขาปลั๊กที่ยืนยันแล้ว → จุดบัดกรี → อุปกรณ์อนุกรม/ทางแยกป้องกัน → จุดเก็บประจุ → วงจรควบคุมไฟ → ตัวกรอง → ขาจ่ายโหลด</li><li><b>อ่านเบอร์และ datasheet</b> ตรวจรุ่นย่อย แพ็กเกจ และทิศขา ไม่ยืม pinout จากชิปหน้าตาคล้ายกัน</li><li><b>บันทึกหลักฐานแต่ละเส้น</b> แยกมองเห็นลาย / วัดต่อถึง / ผ่านชั้นในไม่ทราบ เสียงบี๊บอย่างเดียวไม่รับรองว่าเป็นเน็ตเดียว</li><li><b>ทดสอบมีไฟภายหลัง</b> ต้องรู้ BATT/IG/GND เงื่อนไขเปิดทำงาน และข้อกำหนดเครื่องมือก่อน ระบุโพรบแดง–ดำและโหลดทุกครั้ง</li></ol><h2>เงื่อนไขก่อนใส่ตัวเลขลงภาพ</h2><p>ต้องมีชื่อเน็ต ตำแหน่งแพดจริง กราวด์อ้างอิง สภาวะทดสอบ เครื่องมือ ช่วงค่าคาดหมาย และแหล่งเกณฑ์หรือผลวัดจากกล่องอ้างอิงที่ตรงรุ่นครบ จึงเปลี่ยน “ยังไม่ยืนยัน” เป็นค่าที่ใช้สอนตรวจได้</p><p><b>Ω ไม่ใช่ V:</b> พิกัดทนแรงดันบนคาปาซิเตอร์ ความต้านทานบนตัวต้านทาน และค่าเฉลี่ยของสัญญาณสวิตชิ่งไม่ใช่แรงดันรางเดียวกัน</p>')

for case in cases:
 case['images']=[]
 for index,uid in enumerate(case['files']):
  source=TEMP/f'codex-clipboard-{uid}.png';dest=P/'originals'/f'ecu-{case["id"]:03d}-{index+1}.png';shutil.copyfile(source,dest)
  assert hashlib.sha256(source.read_bytes()).digest()==hashlib.sha256(dest.read_bytes()).digest()
  svg=P/'annotated'/f'ecu-{case["id"]:03d}-{index+1}.svg';svg.write_text(photo_svg(case,index,dest),encoding='utf8')
  case['images'].append(dict(original=dest.relative_to(P).as_posix(),annotated=svg.relative_to(P).as_posix(),sha256=hashlib.sha256(dest.read_bytes()).hexdigest(),size=list(Image.open(dest).size)))
  page(f'<img class="plate" src="../{svg.relative_to(P).as_posix()}"/>','graphic')
 content=f'<h1>กล่อง {case["id"]:02d} • แผนตรวจและสิ่งที่ยังขาด</h1><h2>สิ่งที่ระบุได้</h2><p>{esc(case["identity"])}</p><p>{esc(case["special"])}</p>'
 content+='<h2>ทางไล่วงจรที่จะพิสูจน์</h2><p>เริ่มจากหน้าที่ขาปลั๊กที่ยืนยันแล้ว จับคู่จุดบัดกรีทั้งสองด้าน จากนั้นตรวจอุปกรณ์ที่อยู่ในเส้นทางทีละตัว อ่านเบอร์เพื่อแยกขา IN / OUT / GND / EN / FB หรือขาสั่งงานจริง ก่อนวาดสายเชื่อมเป็นวงจรยืนยัน</p>'
 content+='<table><thead><tr><th>สิ่งที่ต้องบันทึก</th><th>สถานะจากภาพชุดนี้</th></tr></thead><tbody>'+''.join(f'<tr><td>{a}</td><td>{b}</td></tr>' for a,b in [('ขาไฟเข้าและสภาวะเปิด','ยังไม่ยืนยัน — ห้ามต่อไฟตามตำแหน่งหรือสีสาย'),('กราวด์อ้างอิงของจุดวัด','ยังไม่ยืนยัน — ไม่ถือรูยึด/แท็บเป็นกราวด์'),('ขาจ่าย IC และค่าที่ควรพบ','ยังไม่ทราบเบอร์ชัดครบ จึงไม่ระบุค่าทดสอบ'),('ชิ้นส่วนที่เสีย','ยังไม่มีผลวัดหรือการทดสอบยืนยัน'),('จุดเริ่มที่ทำต่อได้','ภาพมาโคร marking / จัดทิศปลั๊ก / ไล่เน็ตขณะไม่มีไฟตามขั้นตอน')])+'</tbody></table>'
 content+='<h2>ตารางสำหรับเติมผลจริง</h2><table><tr><th>จากขา/แพด</th><th>ถึงขา/แพด</th><th>ผล Ω / V</th><th>สภาวะ / แหล่งเกณฑ์</th></tr>'+''.join('<tr><td>________</td><td>________</td><td>________</td><td>________________</td></tr>' for _ in range(3))+'</table><p class="notice">ข้อมูลตอนนี้เป็นแผนที่สำรวจ ไม่ใช่ใบสั่งเปลี่ยน IC หรือผังต่อไฟให้กล่องทำงาน</p>'
 page(content)
 inventory.append(case)

css='''@page{size:A4;margin:12mm 12mm 15mm}*{box-sizing:border-box}body{font-family:"Leelawadee UI",Tahoma,sans-serif;font-size:11pt;line-height:1.4;margin:0;color:#132b3e}section{break-after:page}section:last-child{break-after:auto}h1{font-size:23pt;margin:0 0 6mm}h2{font-size:15pt;margin:5mm 0 2mm}h1,h2{break-after:avoid}p{margin:0 0 3mm;orphans:3;widows:3}li{margin-bottom:3mm}table{width:100%;border-collapse:collapse;font-size:10pt;margin:3mm 0}td,th{border:1px solid #bdcad3;padding:2mm;text-align:left;vertical-align:top}th{background:#edf3f7}tr{break-inside:avoid}.notice{background:#fff2d8;border-left:4px solid #e88909;padding:3mm;margin:3mm 0}.graphic{height:266mm;display:flex;align-items:center;justify-content:center}.plate{width:100%;height:100%;object-fit:contain}a{color:#15638e}'''
(P/'catalog.json').write_text(json.dumps({'cases':inventory,'status':'photo observations; no confirmed live voltage points','sources':[{'id':'F01','url':'https://www.fluke.com/en-us/learn/blog/digital-multimeters/how-to-measure-resistance','scope':'measurement method only; not ECU specifications'},{'id':'T01','url':'https://www.tek.com/en/documents/whitepaper/abcs-probes-primer','scope':'probe reference method only; not ECU specifications'}]},ensure_ascii=False,indent=2),encoding='utf8')
(P/'output/atlas.html').write_text('<!doctype html><html lang="th"><meta charset="utf-8"><title>ECU photo atlas 01–07</title><style>'+css+'</style><body>'+''.join(pages)+'</body></html>',encoding='utf8')
print('Cases:',len(cases),'original photos:',sum(len(c['images']) for c in cases),'planned pages:',len(pages))
